nflict textarea{min-height:140px;font-size:13px}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}.actions button{font:inherit;background:#fff;border:1px solid #dfd2b7;padding:7px;border-radius:5px;cursor:pointer}.pinned{background:#f8f7fc;border-left:3px solid #ac9cce;padding:14px}.pinned-title{display:flex;justify-content:space-between}.pinned>b{font-size:12px;color:#736a84}.pinned .original{max-height:230px;overflow:auto;font-size:12px}.versions>div{padding:12px 0;border-bottom:1px solid #eaeaf0;font-size:12px}.versions>div p{white-space:pre-wrap;max-height:180px;overflow:auto}.footnote{margin-top:22px}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}button:focus-visible,textarea:focus-visible,summary:focus-visible{outline:2px solid #8a76b8;outline-offset:3px}.auxiliary-panel small{display:block;color:#8c8a99;font-size:11px}
.intro,.footnote,.file-name{color:#667085}.auxiliary-panel nav button,.close,.auxiliary-panel small{color:#6f687a}.auxiliary-panel small{font-size:12px}
.auxiliary-panel{border-color:#e2e8f0;color:#334155}.auxiliary-panel nav button.active{border-color:#4f46e5;color:#4f46e5}.auxiliary-panel header{padding:12px 18px}.auxiliary-panel nav button,.close{min-height:36px;font-size:14px}.close{padding:6px 8px;border:1px solid #e2e8f0;border-radius:6px;color:#475569}.panel-content{font-size:15px}.intro,.footnote,.source-scope,.save-state{font-size:13px;color:#64748b}.panel-content h3{font-size:16px;color:#1e293b}.panel-content article,.original{font-size:14px}.link{font-size:14px;color:#4f46e5;min-height:32px}.source-scope,.pinned{background:#f8fafc}.pinned{border-color:#a5b4fc}.opinion-content>textarea{border-color:#cbd5e1;color:#1e293b}.save-state:not(.warning){color:#0f766e}.warning{color:#92400e;background:#fffbeb}summary{color:#475569}button:focus-visible,textarea:focus-visible,summary:focus-visible{outline-color:#4f46e5}
</style>
